window.DECK = {"title": "What holds a job together?", "date": "November 23, 2026", "duration": 50, "description": "Garicano on job boundaries, task pricing and worker sorting; the Messy Jobs tiers; training contracts, expert complementarity and career entry.", "draft_date": "2026-10-25", "author": "Sergio Ocampo", "slides": [{"title": "What holds a job together?", "html": "<p>Task bundles, human earnings, and the training of future experts<\/p><p>Sergio Ocampo<br>ECON 3399 · AI and Robots at Work<\/p>", "notes": "", "minutes": 0.5, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "class": "cover", "id": "s01", "teaching_role": "setup"}, {"title": "A credit analyst does more than calculate repayment risk", "html": "<p>A small firm applies for a loan. The analyst forecasts repayment, asks the borrower about its cash flow, and recommends loan terms.<\/p><p>The analyst also builds a relationship with the client to understand their needs and adapt the analysis to their circumstances.<\/p><p>The conversation reveals seasonal sales. That changes the forecast; the forecast raises new questions for the borrower.<\/p><div class=\"takeaway\">Can AI take over the calculations without losing the context that makes the credit assessment useful?<br>The same work also helps a junior learn to judge credit risk.<\/div>", "notes": "", "minutes": 1.5, "source": "<a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Messy Jobs<\/a> · Garicano’s LBS book talk, Oct. 22, 2026 · pp. 3–4, 9–10; credit-analysis illustration", "id": "s02", "revision": "credit-relationship-2026-10-30", "teaching_role": "setup", "class": "content-centered"}, {"id": "paper-bundles", "title": "Weak Bundle, Strong Bundle", "html": "<div class=\"paper-identity-layout\"><figure><img src=\"figures/paper_bundles.png\" alt=\"Working paper · First page: Weak Bundle, Strong Bundle\"><figcaption>Working paper · First page<\/figcaption><\/figure><div class=\"paper-details\"><p class=\"paper-subtitle\">How AI redraws job boundaries<\/p><p>Luis Garicano, Jin Li, and Yanhui Wu<\/p><p><strong>Working paper · March 30, 2026<\/strong><\/p><p class=\"small\"><a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a><\/p><\/div><\/div>", "notes": "", "minutes": 0, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a> · Working paper · March 30, 2026", "class": "paper-identity content-centered", "teaching_role": "paper_identity"}, {"id": "bundle-careers", "title": "What makes credit analysis a strong bundle?", "html": "<p><strong>Illustration:<\/strong> calculations and borrower judgment support one loan recommendation.<\/p><table class=\"results\"><colgroup><col style=\"width:32%\"><col style=\"width:68%\"><\/colgroup><thead><tr><th>Source of interdependence<\/th><th>Credit-analysis example<\/th><\/tr><\/thead><tbody><tr><td>Unpredictable task demands<\/td><td>New facts emerge in the borrower interview; the required analysis changes.<\/td><\/tr><tr><td>Production spillovers<\/td><td>Seasonal cash flow changes the forecast; the forecast prompts new questions.<\/td><\/tr><tr><td>Joint outcome measurement<\/td><td>The bank values a sound loan decision, combining numbers with borrower context.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">A bundle is weak when its tasks can be separated with little loss of value.<br>A bundle is strong when separating its tasks destroys value.<\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Section 5; <a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Messy Jobs<\/a> · Garicano’s LBS book talk, Oct. 22, 2026 · pp. 9–10", "minutes": 3.0, "teaching_role": "result_interpretation", "revision": "weak-bundle-definition-2026-10-30", "class": "content-centered"}, {"title": "A credit assessment needs both tasks", "html": "<div class=\"equation\">\\[y=q_1^{\\alpha}q_2^{1-\\alpha},\\qquad 0&lt;\\alpha&lt;1\\]<\/div><table class=\"results\"><colgroup><col style=\"width:31%\"><col style=\"width:69%\"><\/colgroup><thead><tr><th>Object<\/th><th>Meaning in the credit example<\/th><\/tr><\/thead><tbody><tr><td>\\(y\\)<\/td><td>Quality-adjusted output: a completed credit assessment.<\/td><\/tr><tr><td>\\(q_1\\)<\/td><td>Task 1: risk calculations and financial forecasts.<\/td><\/tr><tr><td>\\(q_2\\)<\/td><td>Task 2: borrower context and judgment about loan terms.<\/td><\/tr><tr><td>\\(\\alpha\\), \\(1-\\alpha\\)<\/td><td>Output elasticities: the contribution of each task.<\/td><\/tr><tr><td>\\(s_1,s_2\\)<\/td><td>Quantitative and borrower-judgment skills.<\/td><\/tr><tr><td>\\(t_1+t_2=1\\)<\/td><td>Time on tasks 1 and 2 adds up to one workday.<\/td><\/tr><\/tbody><\/table>", "notes": "", "minutes": 2, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), Weak Bundle, Strong Bundle, March 30 version<\/a>", "id": "s04", "teaching_role": "setup", "revision": "skills-time-rows-2026-10-30", "class": "content-centered"}, {"id": "bundle-choices", "title": "Before task automation: production, wages and entry", "html": "<table class=\"results\"><colgroup><col style=\"width:30%\"><col style=\"width:70%\"><\/colgroup><thead><tr><th>Stage<\/th><th>Bundled work (B)<\/th><\/tr><\/thead><tbody><tr><td>Firm / production<\/td><td>Allocate time \\(t_1+t_2=1\\) across both tasks to maximize returns.<\/td><\/tr><tr><td>Competitive pay<\/td><td>The wage equals the value of the worker’s marginal product.<\/td><\/tr><tr><td>Worker participation<\/td><td>Enter credit analysis if the best wage offer is at least outside income \\(w_0\\).<\/td><\/tr><\/tbody><\/table><p><strong>AI-Automation Choice<\/strong><\/p><ul><li>AI capability \\(m\\) to perform task 1.<\/li><li>Two options:<ol style=\"margin:8px 0\"><li>Use AI to assist in task 1 and keep tasks bundled (B).<\/li><li>Automate task 1 and unbundle tasks (U).<\/li><\/ol><\/li><li>Unbundling destroys fraction \\(c\\) of output.<\/li><\/ul>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Sections 2–3", "minutes": 2, "teaching_role": "setup", "revision": "numbered-AI-options-2026-10-30", "class": "content-centered"}, {"title": "AI assistance and autonomous risk calculations", "html": "<table class=\"results\"><colgroup><col style=\"width:50%\"><col style=\"width:50%\"><\/colgroup><thead><tr><th>Assistance B: <span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(\\mu_B(m)\\)<\/span><\/th><th>Autonomous task 1 U: <span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(\\mu_A(m)\\)<\/span><\/th><\/tr><\/thead><tbody><tr><td>AI helps with calculations; the analyst checks them.<\/td><td>AI supplies usable calculations independently.<\/td><\/tr><tr><td>Human time covers both tasks.<br><span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(q_2=t_2s_2\\)<\/span><\/td><td>Human time goes entirely to task 2.<br><span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(q_2=s_2\\)<\/span><\/td><\/tr><tr><td><span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(q_1=\\mu_B(m)^{1-\\eta}(t_1s_1)^\\eta\\)<\/span><\/td><td><span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(q_1=\\mu_A(m)\\)<\/span><\/td><\/tr><tr><td><span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(y_B=\\mu_B(m)^{\\alpha(1-\\eta)}(t_1s_1)^{\\alpha\\eta}(t_2s_2)^{1-\\alpha}\\)<\/span><\/td><td><span class=\"table-math\" style=\"font-size:30px;line-height:1.2\">\\(y_U=(1-c)\\mu_A(m)^\\alpha s_2^{1-\\alpha}\\)<\/span><\/td><\/tr><\/tbody><\/table><p><strong>\\(\\eta\\in(0,1)\\)<\/strong> is the human-input elasticity in task 1.<\/p>", "notes": "", "minutes": 4, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Equation (5); <a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Messy Jobs<\/a> · Garicano’s LBS book talk, Oct. 22, 2026 · pp. 3–4 · Equations (4)–(5), PDF p. 6", "id": "s05", "teaching_role": "setup", "revision": "real-wages-math-size-2026-10-30", "class": "content-centered"}, {"id": "bundle-time-release", "title": "Unbundling frees time for borrower judgment", "html": "<div><p style=\"margin:0 0 10px\">Optimal bundled allocation (<a href=\"#bundle-optimal-time\">derivation<\/a> · <a href=\"#s06\">production functions<\/a>)<\/p><div class=\"equation\">\\[t_1^*=\\frac{\\alpha\\eta}{\\kappa},\\qquad t_2^*=\\frac{1-\\alpha}{\\kappa},\\qquad\\underbrace{\\kappa=\\alpha\\eta+1-\\alpha}_{\\text{Bundled labor share}}\\]<\/div><\/div><figure><img style=\"max-height:240px\" src=\"figures/bundle_time_release.png\" alt=\"Illustration: alpha = 1/2, eta = 3/4, kappa = 7/8. Bundled time: alpha eta/kappa = 3/7 on task 1 and (1-alpha)/kappa = 4/7 on task 2. Unbundled time: t2 = 1 on task 2.\"><\/figure><div class=\"takeaway\">Task-2 capacity: \\(\\kappa/(1-\\alpha)=7/4=1.75\\) times the bundled level.<br>Gain: \\(\\kappa/(1-\\alpha)-1=\\alpha\\eta/(1-\\alpha)=3/4=75\\%\\), with skills unchanged.<\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Section 4.2; illustrative arithmetic", "minutes": 3, "teaching_role": "result_exhibit", "revision": "symbolic-time-example-2026-10-30", "class": "content-centered"}, {"id": "bundle-payoffs", "title": "Real wages depend on revenue shares and output", "html": "<p>Real wages \\(w/P\\) are in units of output. For simplicity we set \\(P=1\\).<\/p><div class=\"equation\">\\[\\frac{w_B}{P}=\\kappa y_B,\\qquad\\frac{w_U}{P}=(1-\\alpha)y_U\\]<\/div><table class=\"results\"><colgroup><col style=\"width:26%\"><col style=\"width:44%\"><col style=\"width:30%\"><\/colgroup><thead><tr><th>Revenue share<br>\\(\\alpha=\\frac12,\\;\\eta=\\frac34\\)<\/th><th>Bundled B<\/th><th>Unbundled U<\/th><\/tr><\/thead><tbody><tr><td>Human input<\/td><td>\\(\\kappa=\\alpha\\eta+1-\\alpha=\\frac78=87.5\\%\\)<\/td><td>\\(1-\\alpha=\\frac12=50\\%\\)<\/td><\/tr><tr><td>AI services<\/td><td>\\(1-\\kappa=\\alpha(1-\\eta)=\\frac18=12.5\\%\\)<\/td><td>\\(\\alpha=\\frac12=50\\%\\)<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Next, compare \\(\\kappa y_B\\) with \\((1-\\alpha)y_U\\): output levels decide between B and U.<br>Full equilibrium also requires total output \\(Y\\) and its market-clearing price.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), Weak Bundle, Strong Bundle, March 30 version<\/a>", "revision": "real-wages-output-link-2026-10-30", "teaching_role": "theory_result", "class": "content-centered"}, {"id": "bundle-revenue-example", "title": "Which arrangement supports the higher real wage?", "html": "<p>Illustration: \\(\\alpha=\\frac12,\\;\\eta=\\frac34,\\;\\kappa=\\frac78,\\;y_B=100,\\;P=1\\).<\/p><table class=\"results\"><colgroup><col style=\"width:18%\"><col style=\"width:30%\"><col style=\"width:30%\"><col style=\"width:22%\"><\/colgroup><thead><tr><th>Unbundled output<\/th><th>Bundled real wage<br>\\(w_B/P\\)<\/th><th>Unbundled real wage<br>\\(w_U/P\\)<\/th><th>Higher wage offer<\/th><\/tr><\/thead><tbody><tr><td>\\(y_U=150\\)<\/td><td>\\(\\kappa y_B=\\frac78(100)=87.5\\)<\/td><td>\\((1-\\alpha)y_U=\\frac12(150)=75\\)<\/td><td>Bundled B<\/td><\/tr><tr><td>\\(y_U=200\\)<\/td><td>\\(\\kappa y_B=\\frac78(100)=87.5\\)<\/td><td>\\((1-\\alpha)y_U=\\frac12(200)=100\\)<\/td><td>Unbundled U<\/td><\/tr><\/tbody><\/table><div class=\"equation\">\\[\\frac{w_U}{P}\\ge\\frac{w_B}{P}\\quad\\Longleftrightarrow\\quad\\frac{y_U}{y_B}\\ge\\frac{\\kappa}{1-\\alpha}=1.75\\]<\/div><div class=\"takeaway\">Unbundling must raise output by at least 75% to offset the smaller human revenue share.<\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Lemma 2; teaching example", "minutes": 2.5, "teaching_role": "result_exhibit", "revision": "real-wages-output-choice-2026-10-30", "class": "content-centered"}, {"id": "bundle-sorting-rule", "title": "Which arrangement offers the worker a higher wage?", "html": "<div class=\"equation\">\\[\\frac{w_U}{w_B}=\\frac{(1-\\alpha)(1-c)}{\\kappa\\Omega_B}\\,\\Gamma(m)\\,s_1^{-\\alpha\\eta}\\quad\\longrightarrow\\quad\\text{Threshold condition for }s_1\\]<\/div><p><strong>Ω<sub>B<\/sub>:<\/strong> output factor from the optimal time split.<br><strong>Γ(m) = μ<sub>A<\/sub>(m)<sup>α<\/sup> / μ<sub>B<\/sub>(m)<sup>α(1−η)<\/sup>:<\/strong> relative autonomous effectiveness.<\/p><ul><li>Stronger calculation skills make the bundle more valuable.<\/li><li>Higher c makes separation less attractive.<\/li><li>Assumption: Γ rises with AI capability m.<\/li><\/ul><p class=\"table-note\"><a href=\"#bundle-cutoff\">The sorting cutoff<\/a> · P and task-2 skill cancel from the comparison.<\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Proposition 1, PDF p. 8", "minutes": 3, "teaching_role": "theory_result", "revision": "region-columns-2026-10-30", "class": "content-centered"}, {"title": "When is the bundle worth keeping?", "html": "<div class=\"columns\" style=\"grid-template-columns:610px 1fr;gap:35px;align-items:center\"><figure><img style=\"display:block;width:100%;height:auto;max-height:445px;object-fit:contain\" src=\"figures/bundle_regimes.png\" alt=\"Figure 1: pure bundling above the solid boundary, an interior region between the boundaries, and pure unbundling below the dashed boundary.\"><figcaption>Horizontal \\(m\\): AI capability.<br>Vertical \\(c\\): value lost when separating tasks.<\/figcaption><\/figure><div style=\"display:flex;flex-direction:column;gap:28px\"><div><h2 style=\"background:#f3f4f6;color:#374151;padding:6px 10px;margin:0 0 12px\">Pure bundling<\/h2><p style=\"margin:0\">All workers perform both tasks.<\/p><\/div><div><h2 style=\"background:#efebfe;color:#60428d;padding:6px 10px;margin:0 0 12px\">Interior<\/h2><p style=\"margin:0\">Some workers bundle and some unbundle;<br>Depends on \\(s_1\\)!<\/p><\/div><div><h2 style=\"background:#dfecfe;color:#315f95;padding:6px 10px;margin:0 0 12px\">Pure unbundling<\/h2><p style=\"margin:0\">Automate task 1 always.<\/p><\/div><\/div><\/div>", "notes": "", "minutes": 3.5, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), Weak Bundle, Strong Bundle, March 30 version<\/a> · Figure 1, PDF p. 10", "id": "s08", "revision": "region-columns-2026-10-30", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "bundle-participation", "title": "The worker can also choose another occupation", "html": "<div class=\"equation\">\\[\\max\\{w_0,\\;w_B(P,s,m),\\;w_U(P,s_2,m;c)\\}\\]<\/div><ul><li>Enter credit-analysis work if its best arrangement pays at least \\(w_0\\).<\/li><li>At a given price, \\(w_0/P\\) is outside earnings in units of output.<\/li><li>Automation depends on \\(s_1\\); entry into unbundled work depends on \\(s_2\\)!<\/li><\/ul><div class=\"equation\">\\[s_2\\ge b_U\\equiv\\left[\\frac{w_0/P}{(1-\\alpha)(1-c)\\mu_A(m)^\\alpha}\\right]^{1/(1-\\alpha)}\\]<\/div><div class=\"takeaway\">Unbundled entry depends on borrower-judgment skill \\(s_2\\).<br>Bundled entry still depends on both \\(s_1\\) and \\(s_2\\).<\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Section 3.1", "minutes": 3, "teaching_role": "theory_result", "revision": "bundled-B-2026-10-30", "class": "content-centered"}, {"id": "bundle-entry-example", "title": "Unbundling can open entry into credit analysis", "html": "<figure><img style=\"max-height:400px\" src=\"figures/bundle_entry_skill_space.png\" alt=\"Fixed-price illustration in calculation skill s1 and borrower-judgment skill s2. With only B, worker 1 is outside and worker 2 is bundled. With U available, worker 1 enters above the horizontal s2 entry threshold of approximately 0.66, while worker 2 remains bundled. Both have s2=0.8.\"><figcaption>Illustration: P = 1, w₀ = 0.4; α = ½, η = ¾, c = 0.4, μ<sub>B<\/sub> = 1.8, μ<sub>A<\/sub> = 2.7.<\/figcaption><\/figure><div class=\"takeaway\">Worker 1 can enter U even though B pays less than outside work.<br>Worker 2 still prefers B at the same borrower-judgment skill.<\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Proposition 2 · illustrative fixed-price calculation", "minutes": 3, "teaching_role": "result_exhibit", "revision": "entry-skill-space-2026-10-30", "class": "content-centered"}, {"id": "bundle-fixed-price", "title": "At a fixed price, better AI expands the residual role", "html": "<table class=\"results\"><colgroup><col style=\"width:31%\"><col style=\"width:69%\"><\/colgroup><thead><tr><th>Margin<\/th><th>Why unbundled employment increases<\/th><\/tr><\/thead><tbody><tr><td>Switching arrangements<\/td><td>The cutoff rises: some B workers switch into U.<\/td><\/tr><tr><td>Entering the occupation<\/td><td>The U entry threshold falls: more task-2 types qualify.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">To explain displacement, the next step must allow product prices to fall.<\/div><ul><li>With inelastic demand, output can rise while revenue falls (<a href=\"#bundle-demand-example\">example<\/a>).<\/li><li>Lower prices make entry harder; <a href=\"#bundle-equilibrium\">market clearing<\/a> determines price and output (<a href=\"#bundle-sorting\">figure<\/a>).<\/li><\/ul>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Proposition 3, Section 3.3", "minutes": 3.5, "teaching_role": "theory_result", "revision": "demand-appendix-2026-10-30", "class": "content-centered"}, {"id": "bundle-outcomes", "title": "Output can double while employment falls", "html": "<figure><img style=\"max-height:350px\" src=\"figures/bundle_output_employment.png\" alt=\"Figure 4, panels A and D: weak bundle (blue) and strong bundle (red); each series starts at 100.\"><figcaption>Figure 4, panels A and D: weak bundle (blue) and strong bundle (red); each series starts at 100.<\/figcaption><\/figure><div class=\"takeaway\">In this calibration, weak-bundle output more than doubles while employment falls about 7%.<br>The price response offsets the expansion in capacity.<\/div><p class=\"table-note\"><a href=\"#bundle-displacement\">When does the price effect dominate productivity?<\/a> · <a href=\"#bundle-income\">Labour income and fixed-worker earnings<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), March 30 version<\/a> · Figure 4A,D, PDF p. 19", "minutes": 3.5, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "messy-tiers", "title": "Three tiers of the autonomy threshold", "html": "<p><strong>Autonomy threshold:<\/strong> AI can deliver finished output well enough to replace paid human work.<\/p><div class=\"columns\" style=\"grid-template-columns:1fr 24px 1fr 24px 1fr;gap:12px;align-items:stretch\"><div style=\"background:#e8eff7;border:1px solid #6e91b9;padding:18px;display:flex;flex-direction:column;gap:16px\"><h2 style=\"margin:0\">Tier 1<\/h2><p style=\"margin:0\"><strong>Single verifiable tasks<\/strong><\/p><p style=\"margin:0\">What sets the threshold?<\/p><\/div><div style=\"display:flex;align-items:center;justify-content:center;color:#4f2683;font-size:30px\" aria-hidden=\"true\">→<\/div><div style=\"background:#e9f3ee;border:1px solid #72a88e;padding:18px;display:flex;flex-direction:column;gap:16px\"><h2 style=\"margin:0\">Tier 2<\/h2><p style=\"margin:0\"><strong>Strong task bundles<\/strong><\/p><p style=\"margin:0\">Why keep tasks together?<\/p><\/div><div style=\"display:flex;align-items:center;justify-content:center;color:#4f2683;font-size:30px\" aria-hidden=\"true\">→<\/div><div style=\"background:#f6eaea;border:1px solid #c88989;padding:18px;display:flex;flex-direction:column;gap:16px\"><h2 style=\"margin:0\">Tier 3<\/h2><p style=\"margin:0\"><strong>Bundles of relationships<\/strong><\/p><p style=\"margin:0\">Who owns relationships?<\/p><\/div><\/div><ul><li><strong>Tier 1:<\/strong> coder, junior contract lawyer, wire-service journalist.<\/li><li><strong>Tier 2:<\/strong> technical sales, litigation lawyer, nurse, field reporter.<\/li><li><strong>Tier 3:<\/strong> senior manager, entrepreneur, AI implementation consultant.<\/li><\/ul>", "notes": "", "source": "<a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Messy Jobs<\/a> · Garicano’s LBS book talk, Oct. 22, 2026 · pp. 3, 6", "minutes": 3, "teaching_role": "result_interpretation", "revision": "messy-tiers-2026-10-30", "class": "content-centered"}, {"id": "messy-tier1", "title": "Tier 1: Single verifiable tasks", "html": "<div class=\"columns\" style=\"align-items:start\"><div><h2>A clean task<\/h2><ul style=\"margin:24px 0 0\"><li>Output and requirements are well defined.<\/li><li>Quality can be checked.<\/li><li>AI can meet the required quality at low cost.<\/li><\/ul><\/div><div><h2>Autonomy can still be limited by<\/h2><ul style=\"margin:24px 0 0\"><li>Technology.<\/li><li>Regulation and accountability.<\/li><li>Customer preference for a human service.<\/li><\/ul><\/div><\/div><p><strong>Examples:<\/strong> a specified program, a standard contract clause, a wire-service summary.<\/p><div class=\"takeaway\">Once AI can supply the task cheaply, human time no longer limits its supply.<br>Competitive pressure can lower the task’s price and human earnings.<\/div>", "notes": "", "source": "<a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Messy Jobs<\/a> · Garicano’s LBS book talk, Oct. 22, 2026 · pp. 3–4, 6–8; task examples adapted", "minutes": 3, "teaching_role": "result_interpretation", "revision": "messy-tiers-2026-10-30", "class": "content-centered"}, {"id": "messy-tier2", "title": "Tier 2: Strong bundles of tasks", "html": "<table class=\"results\"><colgroup><col style=\"width:31%\"><col style=\"width:69%\"><\/colgroup><thead><tr><th>What connects the tasks<\/th><th>Examples beyond credit analysis<\/th><\/tr><\/thead><tbody><tr><td>Unpredictable needs<\/td><td>Technical sales: client needs emerge during the conversation.<\/td><\/tr><tr><td>Production spillovers<\/td><td>Litigation: new evidence changes strategy and what to investigate.<\/td><\/tr><tr><td>Joint quality of the service<\/td><td>Nursing: assessment, explanation and care shape the whole service.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">A task can become automatable before the whole service can be supplied autonomously.<br>When splitting the work destroys value, human + AI can preserve the bundle.<\/div>", "notes": "", "source": "<a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Messy Jobs<\/a> · Garicano’s LBS book talk, Oct. 22, 2026 · pp. 6, 9–10; classroom illustrations", "minutes": 3, "teaching_role": "result_interpretation", "revision": "messy-tiers-2026-10-30", "class": "content-centered"}, {"id": "messy-tier3", "title": "Tier 3: Relationships, authority and implementation", "html": "<table class=\"results\"><colgroup><col style=\"width:30%\"><col style=\"width:70%\"><\/colgroup><thead><tr><th>What holds work together<\/th><th>Examples in organizations<\/th><\/tr><\/thead><tbody><tr><td>Decision-making<\/td><td>A manager chooses a reorganization: some teams gain, others lose.<\/td><\/tr><tr><td>Regulation &amp; accountability<\/td><td>Banking: explain the loan decision and identify who is accountable.<\/td><\/tr><tr><td>Relationships<\/td><td>Consulting: trust helps client staff share unwritten local knowledge.<\/td><\/tr><tr><td>Consensus &amp; implementation<\/td><td>AI implementation: secure support from IT, compliance and operations.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">AI implementation requires changing workflows and responsibilities together.<br>The scarce work includes securing cooperation and carrying out the decision.<\/div>", "notes": "", "source": "<a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Messy Jobs<\/a> · Garicano’s LBS book talk, Oct. 22, 2026 · pp. 8, 15–18; classroom illustrations", "minutes": 4, "teaching_role": "result_interpretation", "revision": "messy-tiers-2026-10-30", "class": "content-centered"}, {"id": "paper-training", "title": "Training in the Age of AI", "html": "<div class=\"paper-identity-layout\"><figure><img src=\"figures/paper_training.png\" alt=\"Working paper · First page: Training in the Age of AI\"><figcaption>Working paper · First page<\/figcaption><\/figure><div class=\"paper-details\"><p class=\"paper-subtitle\">A theory of career viability<\/p><p>Luis Garicano and Luis Rayo<\/p><p><strong>Working paper · March 3, 2026<\/strong><\/p><p class=\"small\"><a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a><\/p><\/div><\/div>", "notes": "", "minutes": 0, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Open the paper<\/a> · Working paper · March 3, 2026", "class": "paper-identity content-centered", "teaching_role": "paper_identity"}, {"title": "Why would a senior still pay to train a junior?", "html": "<p>A senior chooses wages, the knowledge transferred and when the junior graduates.<\/p><ul><li><strong>Objective:<\/strong> maximize discounted junior output minus wages during training.<\/li><li><strong>Constraint:<\/strong> the junior must prefer staying to leaving at every date.<\/li><li><strong>Hiring:<\/strong> the resulting training profit must cover a fixed onboarding cost.<\/li><\/ul><div class=\"takeaway\">The senior receives work; the junior receives knowledge.<br>AI changes how much useful work can finance that exchange.<\/div><p class=\"table-note\"><a href=\"#training-contract\">Formal contract problem and assumptions<\/a><\/p>", "notes": "", "minutes": 2, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), Training in the Age of AI: A Theory of Career Viability, March 3 version<\/a>", "id": "s11", "revision": "results-focus-2026-10-26", "teaching_role": "setup", "class": "content-centered"}, {"id": "training-environment", "title": "What does the senior choose, and why does the junior stay?", "html": "<p>A senior controls a junior’s knowledge path <strong>X(t) ∈ [0, 1]<\/strong>.<br>The junior graduates at time T, when X(T) = 1.<\/p><table class=\"results\"><colgroup><col style=\"width:35%\"><col style=\"width:65%\"><\/colgroup><thead><tr><th>Technology<\/th><th>Meaning<\/th><\/tr><\/thead><tbody><tr><td>AI threshold θ ∈ [0, 1)<\/td><td>Below θ, the junior adds no useful work beyond AI.<\/td><\/tr><tr><td>Output f(X, θ) for X ≥ θ<\/td><td>More knowledge raises output; better AI weakly raises it.<\/td><\/tr><tr><td>After leaving<\/td><td>The junior can produce independently at current knowledge, using AI.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">The senior gives enough initial knowledge to clear θ.<br>Further training exchanges knowledge for junior work.<\/div>", "notes": "", "minutes": 3, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), Training in the Age of AI: A Theory of Career Viability, March 3 version<\/a>", "revision": "definitions-2026-10-29", "teaching_role": "setup", "class": "content-centered"}, {"id": "training-technology", "title": "AI moves the entry floor and can raise the expert ceiling", "html": "<figure><img style=\"max-height:295px\" src=\"figures/training_floor_ceiling.png\" alt=\"Illustrative output functions at AI thresholds 0.1 and 0.6. Labels sit clear of the curves. Dashed zero-output segments are labelled No junior zone, X less than theta: the junior contributes no useful work beyond AI. Entry floors are 20 and 70, and expert ceilings are 101 and 106.\"><figcaption>Teaching illustration. Dashed segments: no junior zone (X &lt; θ), with no useful junior contribution.<\/figcaption><\/figure><table class=\"results\"><colgroup><col style=\"width:33%\"><col style=\"width:33%\"><col style=\"width:34%\"><\/colgroup><thead><tr><th>Entry floor (with AI)<\/th><th>Expert ceiling (with AI)<\/th><th>Expertise leverage R<\/th><\/tr><\/thead><tbody><tr><td>\\(f_{\\min}(\\theta)=f(\\theta,\\theta)\\)<br>Novice who just clears θ.<\/td><td>\\(f_{\\max}(\\theta)=f(1,\\theta)\\)<br>Fully trained graduate.<\/td><td>\\(\\displaystyle R(\\theta)=\\frac{f_{\\max}(\\theta)}{f_{\\min}(\\theta)}\\)<br>Productive growth from training.<br>5.05 → 1.51 as θ rises.<\/td><\/tr><\/tbody><\/table>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Assumption 1; teaching diagram", "minutes": 4.5, "teaching_role": "result_exhibit", "revision": "training-technology-merge-2026-10-30", "class": "content-centered"}, {"id": "training-no-quit", "title": "The promise of expertise must make the junior willing to stay", "html": "<p><strong>Baseline:<\/strong> zero training wages; compensation is future expertise.<br><strong>r:<\/strong> common discount rate; <strong>T:<\/strong> graduation date.<\/p><div class=\"equation\">\\[\\underbrace{e^{-r(T-t)}\\frac{f_{\\max}}{r}}_{\\text{value of staying}}\\;\\ge\\;\\underbrace{\\frac{f(X(t),\\theta)}{r}}_{\\text{value of leaving now}}\\]<\/div><ul><li>Stay: wait until graduation, then receive expert output forever.<\/li><li>Leave: produce forever using knowledge already acquired.<\/li><\/ul><div class=\"takeaway\">The senior cannot delay training indefinitely.<br>The junior must receive enough future expertise to prefer staying.<\/div><p><a href=\"#training-canonical\">The no-quit constraint pins down the output path<\/a><\/p>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Lemma 1; PDF pp. 7–8", "minutes": 3, "teaching_role": "theory_result", "revision": "jobs-theory-2026-10-30", "class": "content-centered"}, {"id": "training-canonical-figure", "title": "Starting farther up the path shortens the contract", "html": "<div class=\"columns\" style=\"align-items:center\"><figure><img style=\"max-height:460px\" src=\"figures/training_canonical_path.png\" alt=\"Original Figure 1A. A lower start u1 gives a longer T1 than a higher start u2, with the same expert ceiling.\"><\/figure><div><ul><li>Horizontal: t − T; zero is graduation.<\/li><li>Vertical: junior output, up to \\(f_{\\max}\\).<\/li><li>Compare a low start u₁ with a higher start u₂.<\/li><\/ul><div class=\"takeaway\">A higher start raises revenue per date.<br>It leaves fewer dates before independence.<\/div><\/div><\/div>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Figure 1A, PDF p. 9", "minutes": 3, "teaching_role": "result_exhibit", "revision": "jobs-theory-2026-10-30", "class": "content-centered"}, {"id": "training-profit-choice-figure", "title": "The AI floor can rule out the profit-maximizing start", "html": "<figure><img style=\"max-height:335px\" src=\"figures/training_start_profit.png\" alt=\"Normalized profit against starting output. Left: a .2 entry floor permits 1/e. Right: a .6 floor forces the senior to start above 1/e.\"><figcaption>u: starting output; Π: training profit; e ≈ 2.718. Gray: starts below the AI floor.<\/figcaption><\/figure><div class=\"takeaway\">The ideal start is \\(f_{\\max}\\) / e; it is feasible when R ≥ e.<br>Otherwise, the senior must start at the AI floor.<\/div><div class=\"table-note actions\" style=\"display:flex;gap:16px;align-items:center;flex-wrap:wrap;font-size:20px\"><a class=\"action\" href=\"#training-start-choice\" style=\"display:inline-block;border:1px solid #cfc4db;border-radius:4px;padding:6px 12px;background:#f6f2fa;text-decoration:none;line-height:1.2\">Profit function and example<\/a><a class=\"action\" href=\"#training-two-regimes\" style=\"display:inline-block;border:1px solid #cfc4db;border-radius:4px;padding:6px 12px;background:#f6f2fa;text-decoration:none;line-height:1.2\">Optimal contracts and profits<\/a><a class=\"action\" href=\"#training-why-e\" style=\"display:inline-block;border:1px solid #cfc4db;border-radius:4px;padding:6px 12px;background:#f6f2fa;text-decoration:none;line-height:1.2\">Why e?<\/a><\/div>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Proposition 1; exact model teaching plot", "minutes": 3, "teaching_role": "result_exhibit", "revision": "jobs-theory-2026-10-30", "class": "content-centered"}, {"title": "Two training regimes", "html": "<figure><img style=\"max-height:350px\" src=\"figures/training_paths.png\" alt=\"Figure 1B–C: the optimal output path during training, with a full-length or compressed contract.\"><figcaption>Figure 1B–C: the optimal output path during training, with a full-length or compressed contract.<\/figcaption><\/figure><div class=\"takeaway\">A higher entry floor forces juniors to start further up the task ladder.<br>Conditional on being hired, they graduate sooner.<\/div><p class=\"table-note\"><a href=\"#training-path-setup\">Reading the training-path axes<\/a><\/p>", "notes": "", "minutes": 4.0, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), Training in the Age of AI: A Theory of Career Viability, March 3 version<\/a> · Figure 1, PDF p. 9", "id": "s14", "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"id": "training-profit-figure", "title": "The pipeline can disappear before expert work disappears", "html": "<figure><img style=\"max-height:350px\" src=\"figures/training_viability.png\" alt=\"Model illustration: fixed expert output. Dotted line: hiring cost F; hire only if Π ≥ F.\"><figcaption>Model illustration: fixed expert output. Dotted line: hiring cost F; hire only if Π ≥ F.<\/figcaption><\/figure><div class=\"takeaway\">Training first shortens; profits then cross the hiring-cost threshold.<br>Experts can remain valuable after the next cohort stops entering.<\/div><div class=\"table-note actions\" style=\"display:flex;gap:16px;align-items:center;flex-wrap:wrap;font-size:20px\"><a class=\"action\" href=\"#training-profit-units\" style=\"display:inline-block;border:1px solid #cfc4db;border-radius:4px;padding:6px 12px;background:#f6f2fa;text-decoration:none;line-height:1.2\">Profit units and hiring cost<\/a><a class=\"action\" href=\"#training-worked-results\" style=\"display:inline-block;border:1px solid #cfc4db;border-radius:4px;padding:6px 12px;background:#f6f2fa;text-decoration:none;line-height:1.2\">Worked hiring examples<\/a><\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), March 3 version<\/a> · Proposition 1; classroom plot with explicitly stated normalization", "minutes": 4.0, "revision": "results-2026-10-25", "teaching_role": "result_exhibit", "class": "content-centered"}, {"title": "What would we expect to observe if the training channel matters?", "html": "<table class=\"results\"><thead><tr><th>Model change<\/th><th>Observable implication<\/th><\/tr><\/thead><tbody><tr><td>Entry floor rises<\/td><td>New juniors start on more advanced tasks.<\/td><\/tr><tr><td>Training compresses<\/td><td>Graduation or promotion is faster among surviving trainees.<\/td><\/tr><tr><td>Profits fall below fixed costs<\/td><td>Junior entry falls even while senior expertise remains valuable.<\/td><\/tr><tr><td>Expert complementarity is strong enough<\/td><td>Entry can survive despite loss of routine junior tasks.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Junior productivity can rise while junior hiring falls.<\/div>", "notes": "", "minutes": 3.0, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), Training in the Age of AI: A Theory of Career Viability, March 3 version<\/a>", "id": "s15", "revision": "results-2026-10-25", "teaching_role": "result_interpretation", "class": "content-centered"}, {"title": "Job survival and career entry are different economic margins", "html": "<table class=\"results\"><colgroup><col style=\"width:31%\"><col style=\"width:31%\"><col style=\"width:38%\"><\/colgroup><thead><tr><th>What we want to understand<\/th><th>Object that matters<\/th><th>Model implication<\/th><\/tr><\/thead><tbody><tr><td>Does the job retain both tasks?<\/td><td>Coordination loss c vs. autonomous advantage<\/td><td>A strong bundle can preserve the human role.<\/td><\/tr><tr><td>Do productivity gains raise earnings?<\/td><td>Human revenue share + product demand<\/td><td>More output can coexist with lower earnings.<\/td><\/tr><tr><td>Will firms train new entrants?<\/td><td>Expertise ratio R + training rent Π* vs. cost F<\/td><td>Incumbent expertise can remain valuable while entry stops.<\/td><\/tr><\/tbody><\/table>", "notes": "", "minutes": 2.5, "source": "ECON 3399 · Course explanation or explicitly labelled classroom illustration.", "id": "s16", "revision": "credit-example-2026-10-30", "teaching_role": "synthesis", "class": "content-centered"}, {"id": "messy-jobs", "title": "Recommended reading: Messy Jobs", "html": "<div class=\"columns\" style=\"grid-template-columns:320px 1fr;align-items:center;gap:45px\"><figure><img src=\"figures/messy_jobs_cover.png\" style=\"max-height:450px;width:auto\" alt=\"Official cover of Messy Jobs: The Work that AI Cannot Reach by Luis Garicano, Jin Li and Yanhui Wu\"><\/figure><div style=\"display:flex;flex-direction:column;gap:20px\"><h2 style=\"margin:0\">The Work that AI Cannot Reach<\/h2><p style=\"margin:0\">Luis Garicano, Jin Li &amp; Yanhui Wu<\/p><p style=\"margin:0\">The book connects job design with coordination, trust and responsibility.<\/p><p style=\"margin:0\"><a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Book website and chapters<\/a><\/p><p style=\"margin:0\"><strong>Interviews with Luis Garicano<\/strong><\/p><ul style=\"margin:0\"><li><a href=\"https://youtu.be/70IebKR2lK0?si=Lhzc21ojy5yuhNua\" target=\"_blank\" rel=\"noopener\">AI and Messy Jobs<\/a><br>Markus’ Academy, episode 164<\/li><li><a href=\"https://youtu.be/-ig0SR3vJ0w?si=l8Jca9GBQnbJg7Yr\" target=\"_blank\" rel=\"noopener\">Messy Jobs: The Work That AI Cannot Reach<\/a><br>LSE School of Public Policy<\/li><\/ul><\/div><\/div>", "notes": "", "source": "<a href=\"https://messyjobs.ai/\" target=\"_blank\" rel=\"noopener\">Official book website &amp; cover<\/a> · Interview links: Markus’ Academy / LSE School of Public Policy", "minutes": 2, "teaching_role": "further_reading", "revision": "jobs-theory-2026-10-30", "class": "content-centered"}, {"title": "Appendix: Write the two production possibilities", "html": "<div class=\"equation\">\\[y_B^g=\\left[\\mu_B^{1-\\eta}(t_1s_1)^\\eta\\right]^\\alpha(t_2s_2)^{1-\\alpha}\\]<\/div><div class=\"equation\">\\[t_1+t_2=1,\\qquad 0&lt;\\eta&lt;1\\]<\/div><div class=\"equation\">\\[y_U=(1-c)\\mu_A^\\alpha s_2^{1-\\alpha}\\]<\/div><p>Unbundling saves human time on task 1, but pays the coordination cost.<\/p><p class=\"table-note\">B/U: bundled/unbundled; μ: AI services; s: skills; t: time; η: human share within task 1. Superscript g denotes gross output.<\/p><p><a href=\"#s05\">Back to the production setup<\/a><\/p>", "notes": "", "minutes": 1.5, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), Weak Bundle, Strong Bundle, March 30 version<\/a>", "id": "s06", "appendix": true, "teaching_role": "optional", "class": "content-centered", "revision": "production-table-merge-2026-10-30"}, {"title": "Appendix: The worker’s share of revenue also changes", "html": "<div class=\"equation\">\\[\\kappa=\\alpha\\eta+1-\\alpha\\]<\/div><div class=\"equation\">\\[w_B=\\kappa P y_B,\\qquad w_U=(1-\\alpha)P y_U\\]<\/div><p>Worker pay: both task contributions when bundled; task 2 when unbundled.<\/p><p class=\"takeaway\">Higher gross output does not automatically imply higher human earnings.<\/p>", "notes": "", "minutes": 1.5, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), Weak Bundle, Strong Bundle, March 30 version<\/a>", "id": "s07", "appendix": true, "teaching_role": "optional", "class": "content-centered", "revision": "bundled-B-2026-10-30"}, {"title": "Appendix: Change capability and the cost of separation", "html": "<div class=\"widget\" data-widget=\"bundle\"><\/div>", "notes": "", "minutes": 3.5, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), Weak Bundle, Strong Bundle, March 30 version<\/a>", "id": "s09", "appendix": true, "teaching_role": "optional", "class": "content-centered", "revision": "jobs-theory-2026-10-30"}, {"title": "Appendix: Why the ratio matters for training", "html": "<p>As knowledge grows, the junior’s outside option improves. Future training must remain valuable enough to retain the junior.<\/p><div class=\"equation\">\\[T^*=\\begin{cases}1/r,&amp;R\\ge e,\\\\ \\log(R)/r,&amp;R&lt;e.\\end{cases}\\]<\/div><p>Entry floor closer to expert ceiling → shorter optimal training.<\/p>", "notes": "", "minutes": 1.5, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), Training in the Age of AI: A Theory of Career Viability, March 3 version<\/a>", "id": "s13", "appendix": true, "teaching_role": "optional", "class": "content-centered", "revision": "jobs-theory-2026-10-30"}, {"id": "training-profit", "title": "Appendix: A shorter training period can make hiring unprofitable", "html": "<table class=\"results\"><thead><tr><th>Regime<\/th><th>Training duration<\/th><th>Gross training profit<\/th><\/tr><\/thead><tbody><tr><td>\\(R\\ge e\\)<\/td><td>\\(1/r\\)<\/td><td>\\(f_{\\max}/(re)\\)<\/td><\/tr><tr><td>\\(1&lt;R&lt;e\\)<\/td><td>\\(\\log R/r\\)<\/td><td>\\(f_{\\min}\\log R/r\\)<\/td><\/tr><\/tbody><\/table><div class=\"equation\">\\[\\text{Hire a junior only if }\\Pi^*\\ge F\\]<\/div><div class=\"takeaway\">R &lt; e means training is compressed.<br>Career collapse occurs only when the remaining profit falls below the fixed hiring and training cost F.<\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), March 3 version<\/a> · Proposition 1 and Corollary 1, PDF p. 10", "minutes": 3.0, "revision": "jobs-theory-2026-10-30", "appendix": true, "teaching_role": "optional", "class": "content-centered"}, {"id": "training-complementarity", "title": "Appendix: How much expert complementarity preserves training?", "html": "<p>In the compressed regime, compare growth in the expert ceiling with growth in the entry floor.<\/p><div class=\"equation\">\\[\\frac{d\\log f_{\\max}}{d\\log f_{\\min}}&gt;1-\\log R\\]<\/div><p>At R = 2, the threshold is about 0.31. A 1% increase in the floor requires more than about 0.31% growth in the ceiling for training profits to rise locally.<\/p><div class=\"takeaway\">A smaller floor–ceiling gap needs stronger expert complementarity to sustain training.<\/div><p><a href=\"#training-complementarity-result\">Back to the complementarity result<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), March 3 version<\/a> · Proposition 2, PDF p. 11", "minutes": 2.5, "revision": "jobs-theory-2026-10-30", "appendix": true, "teaching_role": "optional", "class": "content-centered"}, {"id": "bundle-optimal-time", "title": "Optimal time allocation in bundled production", "html": "<p>At given skills and AI, maximize output subject to \\(t_1+t_2=1\\).<\/p><div class=\"equation\">\\[\\max_{0&lt;t_1&lt;1}\\;\\alpha\\eta\\log t_1+(1-\\alpha)\\log(1-t_1)\\]<\/div><div class=\"equation\">\\[\\frac{\\alpha\\eta}{t_1}=\\frac{1-\\alpha}{1-t_1}\\]<\/div><div class=\"equation\">\\[t_1^*=\\frac{\\alpha\\eta}{\\kappa},\\qquad t_2^*=\\frac{1-\\alpha}{\\kappa},\\qquad \\kappa\\equiv\\alpha\\eta+1-\\alpha\\]<\/div><div class=\"takeaway\">Time goes to each human contribution in proportion to its output elasticity.<\/div><p class=\"table-note\"><a href=\"#bundle-time-release\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Lemma 1, PDF p. 6", "minutes": 3, "teaching_role": "theory_result", "revision": "competitive-interpretation-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "bundle-cutoff", "title": "A task-1 skill cutoff separates the two arrangements", "html": "<div class=\"equation\">\\[s_1^*(m,c)=\\left[\\frac{(1-\\alpha)(1-c)\\Gamma(m)}{\\kappa\\Omega_B}\\right]^{1/(\\alpha\\eta)}\\]<\/div><table class=\"results\"><colgroup><col style=\"width:54%\"><col style=\"width:46%\"><\/colgroup><thead><tr><th>Among workers entering the occupation<\/th><th>Preferred arrangement<\/th><\/tr><\/thead><tbody><tr><td>\\(s_1&lt;s_1^*\\): weaker task-1 skill<\/td><td>AI supplies task 1 autonomously: U<\/td><\/tr><tr><td>\\(s_1&gt;s_1^*\\): stronger task-1 skill<\/td><td>Human retains both tasks: B<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Better AI raises the cutoff → more types prefer U.<br>A larger separation loss lowers it → more types retain B.<\/div><p class=\"table-note\"><a href=\"#bundle-sorting-rule\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Equation (15), PDF p. 8", "minutes": 3, "teaching_role": "theory_result", "revision": "bundled-B-2026-10-30", "class": "content-centered", "appendix": true}, {"title": "Demand determines the price of the extra output", "html": "<p><strong>Y:<\/strong> total output of the occupation. <strong>P(Y):<\/strong> its market price.<\/p><div class=\"equation\">\\[P(Y)=Y^{-1/\\varepsilon},\\qquad \\varepsilon&lt;1\\text{ in the benchmark}\\]<\/div><p><strong>ε<\/strong> is the price elasticity of demand: a 1% price cut raises demand by less than 1% when ε &lt; 1.<\/p><div class=\"takeaway\">AI raises capacity; selling the extra output requires a lower price.<br>If demand responds too little, lower earnings can push workers out.<\/div><p class=\"table-note\"><a href=\"#bundle-demand-example\">Back to the main discussion<\/a><\/p>", "notes": "", "minutes": 3.0, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), Weak Bundle, Strong Bundle, March 30 version<\/a>", "id": "s10", "revision": "definitions-2026-10-29", "teaching_role": "result_interpretation", "class": "content-centered", "appendix": true}, {"id": "bundle-entry-setup", "title": "Choosing an arrangement is different from entering the occupation", "html": "<p>Outside earnings are w₀; product price is P*. The ratio \\(w_0/P^*\\) expresses the outside option in units of output.<\/p><table class=\"results\"><colgroup><col style=\"width:36%\"><col style=\"width:64%\"><\/colgroup><thead><tr><th>Figure 2<\/th><th>How to read it<\/th><\/tr><\/thead><tbody><tr><td>Each point \\((s_1,s_2)\\)<\/td><td>One worker type, with skills in both tasks.<\/td><\/tr><tr><td>Gray / blue / purple<\/td><td>Outside occupation / unbundled work / bundled work.<\/td><\/tr><tr><td>b_B / b_U boundaries<\/td><td>Chosen earnings just equal the outside option.<\/td><\/tr><tr><td>s₁* sorting boundary<\/td><td>Among entrants, which arrangement pays more?<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">AI can open the occupation to people with weak task-1 skills.<br>Entry still requires enough task-2 skill to beat the outside option.<\/div><p class=\"table-note\"><a href=\"#bundle-sorting\">Back to the main discussion<\/a><\/p>", "notes": "", "minutes": 3, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), March 30 version<\/a> · Figure 2, PDF p. 15", "revision": "bundled-B-2026-10-30", "teaching_role": "setup", "class": "content-centered", "appendix": true}, {"id": "bundle-displacement", "title": "When does higher productivity push workers out?", "html": "<p>For an unbundled worker at fixed skill and c:<\/p><div class=\"equation\">\\[\\frac{d\\log w_U}{dm}=\\frac{d\\log P^*}{dm}+\\alpha\\frac{d\\log\\mu_A}{dm}\\]<\/div><ul><li>Direct productivity gain: AI raises the value of the residual human input.<\/li><li>Market response: extra output lowers the price of the service.<\/li><li>If the price effect dominates, marginal workers take the outside option.<\/li><\/ul><div class=\"takeaway\">In pure unbundling, employment falls if the price effect dominates the productivity gain.<\/div><p class=\"table-note\"><a href=\"#bundle-outcomes\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Proposition 5 &amp; Corollary 2", "minutes": 3, "teaching_role": "theory_result", "revision": "bundled-B-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "training-contract", "title": "What contract does the senior choose?", "html": "<p>Choose wages w(t), knowledge X(t), and graduation time T:<\/p><div class=\"equation\">\\[\\max_{w,X,T}\\;\\Pi=\\int_0^T e^{-rt}\\big[f(X(t),\\theta)-w(t)\\big]dt\\]<\/div><ul><li>Knowledge reaches 1 at graduation; wages cannot be negative.<\/li><li>At every date, staying must be worth at least as much as leaving.<\/li><li>Hire only if maximized training profit Π* covers fixed cost F.<\/li><\/ul><div class=\"takeaway\">r is the discount rate.<br>After graduation, the junior can earn the full expert return independently.<\/div><p class=\"table-note\"><a href=\"#s11\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Section 2, PDF p. 7", "minutes": 3, "teaching_role": "setup", "revision": "jobs-theory-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "training-why-e", "title": "Why does the number e appear?", "html": "<p>Choose the starting output that maximizes training profit:<\/p><div class=\"equation\">\\[\\max_{f_{\\min}\\le u\\le f_{\\max}}\\;\\frac{u}{r}\\log\\frac{f_{\\max}}{u}\\]<\/div><div class=\"equation\">\\[\\frac{d\\Pi}{du}=\\frac{1}{r}\\left[\\log\\frac{f_{\\max}}{u}-1\\right]=0\\]<\/div><div class=\"equation\">\\[u^{\\mathrm{ideal}}=\\frac{f_{\\max}}{e},\\qquad T^{\\mathrm{ideal}}=\\frac{1}{r}\\]<\/div><div class=\"takeaway\">The ideal start is feasible only if \\(f_{\\min}\\) ≤ \\(f_{\\max}\\) / e.<br>Equivalently, the expertise leverage ratio must satisfy R ≥ e.<\/div><p class=\"table-note\"><a href=\"#training-profit-choice-figure\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Proposition 1, PDF p. 10", "minutes": 3, "teaching_role": "theory_result", "revision": "jobs-theory-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "training-path-setup", "title": "Read the training paths before comparing their lengths", "html": "<table class=\"results\"><colgroup><col style=\"width:42%\"><col style=\"width:58%\"><\/colgroup><thead><tr><th>Reading the next figure<\/th><th>Meaning<\/th><\/tr><\/thead><tbody><tr><td>Horizontal axis: t − T<\/td><td>Time until graduation; zero is the end.<\/td><\/tr><tr><td>Vertical axis: output<\/td><td>u* at entry; \\(f_{\\max}\\) at graduation.<\/td><\/tr><tr><td>Full-length panel<\/td><td>The floor lies below \\(f_{\\max}\\)/e; duration = 1/r.<\/td><\/tr><tr><td>Compressed panel<\/td><td>The floor lies above \\(f_{\\max}\\)/e; duration &lt; 1/r.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Compare the floor with the ideal start, holding the expert ceiling fixed.<\/div><p class=\"table-note\"><a href=\"#s14\">Back to the main discussion<\/a><\/p>", "notes": "", "minutes": 3, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), Training in the Age of AI: A Theory of Career Viability, March 3 version<\/a> · Figure 1, PDF p. 9", "revision": "definitions-2026-10-29", "teaching_role": "setup", "class": "content-centered", "appendix": true}, {"id": "training-complementarity-result", "title": "How much must expert output rise?", "html": "<p>In the compressed regime, define the expert-to-entry response as the percentage increase in the ceiling per 1% increase in the floor.<\/p><div class=\"equation\">\\[\\frac{d\\log f_{\\max}}{d\\log f_{\\min}}&gt;1-\\log R\\quad\\longrightarrow\\quad d\\Pi^*&gt;0\\]<\/div><table class=\"results\"><colgroup><col style=\"width:38%\"><col style=\"width:62%\"><\/colgroup><thead><tr><th>Current expertise ratio R<\/th><th>Ceiling response needed per 1% floor increase<\/th><\/tr><\/thead><tbody><tr><td>2.0<\/td><td>More than 0.31%<\/td><\/tr><tr><td>1.2<\/td><td>More than 0.82%<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">A smaller expertise gap requires stronger expert complementarity to preserve training rents.<\/div><p class=\"table-note\"><a href=\"#training-complementarity\">Derivation and interpretation<\/a><\/p><p class=\"table-note\"><a href=\"#training-profit-figure\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Proposition 2, PDF pp. 11–12", "minutes": 3, "teaching_role": "theory_result", "revision": "jobs-theory-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "bundle-demand-example", "title": "Inelastic demand can reduce revenue as output rises", "html": "<p><strong>Price per credit assessment:<\/strong> P(Y) = Y<sup>−1/ε<\/sup>.<br>ε = 0.8: a 1% price cut raises demand by only 0.8%.<\/p><table class=\"results\"><colgroup><col style=\"width:42%\"><col style=\"width:24%\"><col style=\"width:34%\"><\/colgroup><thead><tr><th>Market outcome<\/th><th>Initially<\/th><th>After 10% more output<\/th><\/tr><\/thead><tbody><tr><td>Output Y<\/td><td>100<\/td><td>110<\/td><\/tr><tr><td>Price P<\/td><td>100<\/td><td>88.8<\/td><\/tr><tr><td>Total revenue PY<\/td><td>100<\/td><td>97.6<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">Consumers buy more, but the price falls proportionally further.<br>More productive work need not generate more income for its suppliers.<\/div><p class=\"table-note\">Illustration: initial indices = 100; output rises 10%. <a href=\"#s10\">Demand and employment<\/a> · <a href=\"#bundle-fixed-price\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Section 4.1; illustrative arithmetic", "minutes": 2.5, "teaching_role": "result_exhibit", "revision": "demand-appendix-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "bundle-equilibrium", "title": "Prices and worker participation must agree in equilibrium", "html": "<table class=\"results\"><colgroup><col style=\"width:40%\"><col style=\"width:60%\"><\/colgroup><thead><tr><th>Step<\/th><th>What the model determines<\/th><\/tr><\/thead><tbody><tr><td>1. Given a candidate price P<\/td><td>Wage offers allocate workers to B, U or outside work.<\/td><\/tr><tr><td>2. Add their production<\/td><td>Total assessments Y; analysts \\(N=N_B+N_U\\).<\/td><\/tr><tr><td>3. Apply market demand<\/td><td>The implied price is P(Y) = Y^(−1/ε).<\/td><\/tr><\/tbody><\/table><div class=\"equation\">\\[P^*=P\\big(Y(P^*;m,c,w_0)\\big)\\]<\/div><div class=\"takeaway\">A lower price raises \\(w_0/P\\) and makes entry harder.<br>The equilibrium balances productive capacity against demand.<\/div><p class=\"table-note\"><a href=\"#s09\">Interactive bundle comparison<\/a> · <a href=\"#bundle-fixed-price\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li &amp; Wu (2026)<\/a> · March 30 version · Proposition 4, Section 4.1", "minutes": 3, "teaching_role": "theory_result", "revision": "demand-appendix-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "bundle-sorting", "title": "Unbundling changes who can enter the occupation", "html": "<figure><img style=\"max-height:315px\" src=\"figures/bundle_sorting.png\" alt=\"Figure 2. Horizontal: task-1 skill s₁; vertical: task-2 skill s₂. Capability m = 0.8; each panel changes c.\"><figcaption>Skills s₁ (horizontal), s₂ (vertical); m = 0.8; each panel changes c.<br>Gray: outside. Blue: U. Purple: B. Vertical s₁*: sorting; b_U / b_B: entry.<\/figcaption><\/figure><div class=\"takeaway\">When AI supplies task 1, entry into the residual job depends on task-2 skill.<br>Workers previously excluded by weak task-1 skill can qualify.<\/div><p class=\"table-note\"><a href=\"#bundle-entry-setup\">Reading the entry boundaries<\/a> · <a href=\"#bundle-fixed-price\">Back to the main discussion<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), March 30 version<\/a> · Figure 2, PDF p. 15", "minutes": 3.5, "revision": "demand-appendix-2026-10-30", "teaching_role": "result_exhibit", "class": "content-centered", "appendix": true}, {"id": "bundle-income", "title": "The income loss is not just a change in worker composition", "html": "<figure><img style=\"max-height:335px\" src=\"figures/bundle_income_earnings.png\" alt=\"Figure 4, B–C. Labour income from this occupation and earnings of a fixed worker; indices start at 100.\"><figcaption>Figure 4, B–C. Labour income from this occupation and earnings of a fixed worker; indices start at 100. · <a href=\"#bundle-outcomes\">Back to results<\/a><\/figcaption><\/figure><div class=\"takeaway\">Weak-bundle labour income falls about 12%.<br>Strong bundles delay the drop until capability m ≈ 2.68; keeping the same worker type does not remove the earnings loss.<\/div>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano, Li and Wu (2026), March 30 version<\/a> · Figure 4B,C, PDF p. 19", "minutes": 4.0, "revision": "bundled-B-2026-10-30", "teaching_role": "result_exhibit", "class": "content-centered", "appendix": true}, {"id": "training-canonical", "title": "The no-quit constraint pins down the output path", "html": "<p>The senior transfers enough knowledge to make the constraint bind: (<a href=\"#training-no-quit\">Back<\/a>)<\/p><div class=\"equation\">\\[f(X(t),\\theta)=e^{-r(T-t)}f_{\\max}\\]<\/div><div class=\"equation\">\\[f(X(t),\\theta)=u e^{rt},\\qquad u\\equiv f(X(0),\\theta)\\]<\/div><ul><li>Output grows at rate r along the chosen contract.<\/li><li>Starting output u must be at least the entry floor \\(f_{\\min}\\).<\/li><li>A higher start puts the junior closer to graduation.<\/li><\/ul><div class=\"takeaway\">The exponential path follows from incentives.<br>The model lets the senior choose how quickly knowledge rises.<\/div>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Lemma 1, Equation (4)", "minutes": 3, "teaching_role": "theory_result", "revision": "jobs-theory-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "training-start-choice", "title": "The senior trades off a higher output flow against a longer contract", "html": "<div class=\"equation\">\\[T(u)=\\frac{1}{r}\\log\\frac{f_{\\max}}{u}\\]<\/div><div class=\"equation\">\\[\\Pi(u)=\\int_0^{T(u)}e^{-rt}u e^{rt}dt=uT(u)=\\frac{u}{r}\\log\\frac{f_{\\max}}{u}\\]<\/div><table class=\"results\"><colgroup><col style=\"width:35%\"><col style=\"width:25%\"><col style=\"width:40%\"><\/colgroup><thead><tr><th>Starting output u<\/th><th>Duration T<\/th><th>Gross training profit Π<\/th><\/tr><\/thead><tbody><tr><td>20<\/td><td>8.05<\/td><td>160.94<\/td><\/tr><tr><td>36.79<\/td><td>5.00<\/td><td>183.94<\/td><\/tr><tr><td>60<\/td><td>2.55<\/td><td>153.25<\/td><\/tr><\/tbody><\/table><p class=\"table-note\">Illustration: expert output = 100; r = 0.2 per time unit; a low enough entry floor. · <a href=\"#training-profit-choice-figure\">Back to the profit graph<\/a><\/p>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Equations (5)–(6); illustrative arithmetic", "minutes": 3, "teaching_role": "result_exhibit", "revision": "jobs-theory-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "training-two-regimes", "title": "Two optimal contracts, depending on the floor-to-ceiling gap", "html": "<table class=\"results\"><colgroup><col style=\"width:26%\"><col style=\"width:36%\"><col style=\"width:38%\"><\/colgroup><thead><tr><th>Result<\/th><th>Full length: R ≥ e<\/th><th>Compressed: 1 &lt; R &lt; e<\/th><\/tr><\/thead><tbody><tr><td>Start u*<\/td><td>\\(f_{\\max}/e\\)<\/td><td>\\(f_{\\min}\\)<\/td><\/tr><tr><td>Duration T*<\/td><td>\\(1/r\\)<\/td><td>\\(\\log R/r\\)<\/td><\/tr><tr><td>Gross profit Π*<\/td><td>\\(f_{\\max}/(re)\\)<\/td><td>\\(f_{\\min}\\log R/r\\)<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">For R ≥ e, a previously profitable career remains viable.<br>For R &lt; e, shorter training may not cover the fixed hiring cost.<\/div><p class=\"table-note\"><a href=\"#training-profit-choice-figure\">Back to the profit graph<\/a><\/p>", "notes": "", "source": "<a href=\"https://www.dropbox.com/scl/fi/f4qkgvr27hue1xqo9ko0c/2026.05.14.-Training-in-the-age-of-AI.pdf?rlkey=1wq5vd35wkc9rzbnhdjckxp49&amp;dl=1\" target=\"_blank\" rel=\"noopener\">Garicano &amp; Rayo (2026)<\/a> · March 3 version · Proposition 1, PDF p. 10", "minutes": 3, "teaching_role": "theory_result", "revision": "jobs-theory-2026-10-30", "class": "content-centered", "appendix": true}, {"id": "training-profit-units", "title": "Hiring compares the value of training with a fixed cost", "html": "<p><strong>Π:<\/strong> discounted junior output minus training wages before graduation.<br><strong>F:<\/strong> fixed hiring and onboarding cost. Hire only if <strong>Π ≥ F<\/strong>.<\/p><table class=\"results\"><colgroup><col style=\"width:47%\"><col style=\"width:53%\"><\/colgroup><thead><tr><th>Next graph / table<\/th><th>Units<\/th><\/tr><\/thead><tbody><tr><td>\\(x=f_{\\min}/f_{\\max}=1/R\\)<\/td><td>Entry output as a fraction of expert output.<\/td><\/tr><tr><td>\\(rT\\)<\/td><td>Duration multiplied by the discount rate.<\/td><\/tr><tr><td>\\(r\\Pi/f_{\\max}\\); \\(rF/f_{\\max}=0.20\\)<\/td><td>Profit and cost in the same normalized units.<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">The exercise holds expert output fixed and raises entry output.<br>The plotted duration is only a candidate once profit falls below the hiring cost.<\/div><p class=\"table-note\"><a href=\"#training-profit-figure\">Back to career viability<\/a><\/p>", "notes": "", "minutes": 3, "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), March 3 version<\/a> · Proposition 1; classroom plot with explicitly stated normalization", "revision": "definitions-2026-10-29", "teaching_role": "setup", "class": "content-centered", "appendix": true}, {"id": "training-worked-results", "title": "Faster training does not imply more entry", "html": "<p class=\"small\">Hold expert output fixed. Express time and profits in normalized units; set the hiring cost to 0.20.<\/p><table class=\"results\"><thead><tr><th>Entry floor / expert ceiling<\/th><th>Candidate duration<\/th><th>Gross profit<\/th><th>Hire?<\/th><\/tr><\/thead><tbody><tr><td>0.20<\/td><td>1.00<\/td><td>0.368<\/td><td>Yes<\/td><\/tr><tr><td>0.50<\/td><td>0.69<\/td><td>0.347<\/td><td>Yes<\/td><\/tr><tr><td>0.80<\/td><td>0.22<\/td><td>0.179<\/td><td>No<\/td><\/tr><\/tbody><\/table><div class=\"takeaway\">At the high entry floor, an expert remains productive, but the remaining training surplus cannot cover the cost of bringing in a junior.<\/div><p class=\"table-note\"><a href=\"#training-profit-figure\">Back to career viability<\/a><\/p>", "notes": "", "source": "<a href=\"https://sites.google.com/site/luisgaricano/teaching\" target=\"_blank\" rel=\"noopener\">Garicano and Rayo (2026), March 3 version<\/a> · Proposition 1 and Corollary 1, PDF p. 10 · <a href=\"data/results_focus_training.csv\">Exact classroom calculations<\/a>", "minutes": 3.5, "teaching_role": "result_exhibit", "revision": "results-focus-2026-10-26", "class": "content-centered", "appendix": true}], "revision_date": "2026-10-30", "revision_focus": "Student-facing definitions, worked measurement examples, and setup before model and empirical exhibits; preserve results.", "pacing": {"main_slides": 32, "appendix_slides": 24, "guidance": "Aim for roughly 70% results and interpretation / 30% question and setup in delivery. Do not omit necessary definitions to hit an exact split; slide timings remain rough preparation aids.", "length_constraint_minutes": null, "note": "Expanded and tightened October 30. Sergio explicitly removed the 50-minute constraint; duration=50 retains the original planning slot only. Main explanations and worked results remain; optional derivations and repeated figure guides are linked in the appendix."}, "content_minutes": 88.0, "hideNotes": true};
